/*---
description: NFC agrees with Node for every code point U+0F0000 through U+0FFFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3857279429, 763034053, 3458675141, 4128432581, 3316466117, 3869088197, 64180677, 1294367173, 1600618949, 2098575813, 2672925125, 2971378117, 1879744965, 64156101, 2551919045, 1313184197];
const blocks = ["NFC U+0F0000-U+0F0FFF", "NFC U+0F1000-U+0F1FFF", "NFC U+0F2000-U+0F2FFF", "NFC U+0F3000-U+0F3FFF", "NFC U+0F4000-U+0F4FFF", "NFC U+0F5000-U+0F5FFF", "NFC U+0F6000-U+0F6FFF", "NFC U+0F7000-U+0F7FFF", "NFC U+0F8000-U+0F8FFF", "NFC U+0F9000-U+0F9FFF", "NFC U+0FA000-U+0FAFFF", "NFC U+0FB000-U+0FBFFF", "NFC U+0FC000-U+0FCFFF", "NFC U+0FD000-U+0FDFFF", "NFC U+0FE000-U+0FEFFF", "NFC U+0FF000-U+0FFFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 983040 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
